import {mergeObservations,retainFrames,observationPayload,viewChanged,SCAN_INTERVAL} from './live-core.js';
export function newScan(){return {id:crypto.randomUUID(),date:new Date().toISOString(),status:'paused',elapsed:0,entries:[],frames:[],dismissed:[],overview:'',incomplete:false,saved:false,error:''};}
export class LiveSession{
 constructor({scan=newScan(),save,analyze,capture,stopCamera,onUpdate=()=>{},now=()=>Date.now(),cloudReady=true}){Object.assign(this,{scan,save,analyze,capture,stopCamera,onUpdate,now,cloudReady});this.inFlight=null;this.lastAttempt=scan.lastAttemptAt??-Infinity;this.hash=null;this.failures=0;this.started=null;this.saves=Promise.resolve();}
 emit(){this.onUpdate(this.scan);}
 async checkpoint(){const snapshot=structuredClone(this.scan);snapshot.saved=true;snapshot.elapsed=this.duration();const operation=this.saves.catch(()=>{}).then(()=>this.save(snapshot));this.saves=operation;try{await operation;this.scan.saved=true;return true;}catch{this.stop();this.scan.status='paused';this.scan.saved=false;this.scan.error='Storage is full or unavailable. Capture is paused. Free space in My history, then resume to retry saving.';this.emit();return false;}}
 stop(){this.stopCamera();if(this.started!==null){this.scan.elapsed+=Math.max(0,this.now()-this.started);this.started=null;}}
 duration(){return this.scan.elapsed+(this.started===null?0:Math.max(0,this.now()-this.started));}
 async run(){if(this.inFlight||this.scan.status==='finalizing')return false;this.scan.status='scanning';this.scan.error='';this.failures=0;this.started=this.now();this.emit();return this.checkpoint();}
 async pause(reason='Scan paused. Tap Resume to continue.'){if(this.scan.status!=='scanning')return;this.stop();this.scan.status='paused';this.scan.error=reason;this.emit();await this.checkpoint();}
 step(){if(this.inFlight||this.scan.status!=='scanning'||this.now()-this.lastAttempt<SCAN_INTERVAL)return this.inFlight||Promise.resolve();this.lastAttempt=this.now();this.scan.lastAttemptAt=this.lastAttempt;this.inFlight=this.inspect().finally(()=>{this.inFlight=null;this.emit();});return this.inFlight;}
 async inspect(){try{const frame=await this.capture();if(this.scan.status!=='scanning')return;if(!viewChanged(this.hash,frame.hash)){this.scan.note='View unchanged. Move slowly to show another angle.';this.emit();return;}
 this.scan.frames=retainFrames(this.scan.frames,frame);this.scan.note='Analyzing this view…';if(!await this.checkpoint())return;this.emit();
 if(!this.cloudReady){this.scan.note='Local AR is active. Keep moving slowly; cloud verification is optional.';await this.checkpoint();this.emit();return;}
 const answer=await this.analyze({mode:'live-frame',photo:await framePhoto(frame),observations:observationPayload(this.scan.entries)});
 this.scan.entries=mergeObservations(this.scan.entries,answer,this.scan.dismissed);this.scan.incomplete||=answer.incomplete===true||answer.items.length>30;this.scan.overview=typeof answer.overview==='string'?answer.overview.slice(0,400):this.scan.overview;this.hash=frame.hash;this.failures=0;this.scan.note=this.scan.entries.length?'Updated. Show another angle of the same pile.':'No waste identified yet. Move closer in good light.';this.scan.error='';await this.checkpoint();this.emit();
 }catch(e){this.failures++;this.scan.error=e.message||'This view could not be analyzed.';if(this.failures>=3&&this.scan.status==='scanning'){this.stop();this.scan.status='paused';this.scan.error+=' Analysis paused after three failures. Tap Resume to try again.';}await this.checkpoint();this.emit();}}
 async finish(){if(this.scan.status==='finalizing')return;this.stop();this.scan.status='finalizing';this.scan.error='';this.scan.note='Combining the saved views…';this.emit();if(this.inFlight)await this.inFlight;if(!await this.checkpoint())return;
 try{if(!this.scan.frames.length)throw Error('No snapshots were captured. Resume and show your waste, then finish.');if(!this.cloudReady){this.scan.status='complete';this.scan.error='';this.scan.note='Local scan complete. Add an AI key later to verify the saved views with Gemini.';}else{const photos=await Promise.all(this.scan.frames.map(framePhoto));const answer=await this.analyze({mode:'live-final',photos,observations:observationPayload(this.scan.entries)});this.scan.entries=mergeObservations(this.scan.entries,answer,this.scan.dismissed);this.scan.overview=typeof answer.overview==='string'?answer.overview.slice(0,400):this.scan.overview;this.scan.incomplete||=answer.incomplete===true||answer.items.length>30;this.scan.status='complete';this.scan.error='';this.scan.note='Scan complete. Results and selected photos saved on this device.';}}catch(e){this.scan.status='partial';this.scan.error=e.message||'Final analysis failed.';this.scan.note='Partial scan: provisional discoveries are preserved. Retry final analysis or resume scanning.';}
 await this.checkpoint();this.emit();}
}
export async function framePhoto(frame){const bytes=new Uint8Array(await frame.blob.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));return {mime:'image/jpeg',data:'data:image/jpeg;base64,'+btoa(binary)};}
